class DynamicCarsLoader{constructor(options={}){this.apiBaseUrl=options.apiBaseUrl||"";this.selectElement=options.selectElement||document.getElementById("vehicle_type");this.onLoad=options.onLoad||this.defaultOnLoad;this.onError=options.onError||this.defaultOnError;this.defaultImagePath="/uploads/placeholder.png"}async loadAvailableCars(){try{const response=await fetch(`${this.apiBaseUrl}/api/cars/`);if(!response.ok){throw new Error(`HTTP error! status: ${response.status}`)}const cars=await response.json();this.populateSelect(cars);this.onLoad(cars)}catch(error){this.onError(error.message)}}populateSelect(cars){if(!this.selectElement){return}this.selectElement.innerHTML="";cars.forEach(car=>{const option=document.createElement("option");option.value=car.id;option.textContent=`${car.make_name} ${car.model_name} (${car.production_year})`;option.setAttribute("data-src",car.head_image||this.defaultImagePath);option.setAttribute("data-car-id",car.id);option.setAttribute("data-daily-price",car.price_policy?.["1-2"]||"0");option.setAttribute("data-car-details",JSON.stringify(car));option.dataset.year=car.production_year||car.year||"-";this.selectElement.appendChild(option)});if(cars.length===0){const fallbackOption=document.createElement("option");fallbackOption.value="";fallbackOption.textContent="No cars available";fallbackOption.disabled=true;this.selectElement.appendChild(fallbackOption)}else{this.selectElement.selectedIndex=0}this.selectElement.dispatchEvent(new Event("change"));this.setupVehicleSelectionHandler()}setupVehicleSelectionHandler(){this.selectElement.addEventListener("change",()=>{this.updateVehicleInfo()})}updateVehicleInfo(){const selectedOption=this.selectElement.options[this.selectElement.selectedIndex];const vehicleInfo=document.getElementById("selected-vehicle-info");if(!selectedOption||!selectedOption.value||!vehicleInfo){if(vehicleInfo)vehicleInfo.style.display="none";return}try{const carDetails=JSON.parse(selectedOption.getAttribute("data-car-details"));const displayName=`${carDetails.make_name||""} ${carDetails.model_name||""}`.trim()||selectedOption.textContent;let imageUrl;if(carDetails.head_image){if(carDetails.head_image.startsWith("http")){imageUrl=carDetails.head_image}else{imageUrl=(window.API_BASE_URL||"")+carDetails.head_image}}else{imageUrl=(window.API_BASE_URL||"")+"/uploads/placeholder.png"}const vehicleImage=document.getElementById("vehicle-image");if(vehicleImage){vehicleImage.src=imageUrl;vehicleImage.alt=displayName}const vehicleName=document.getElementById("vehicle-name");if(vehicleName){vehicleName.textContent=displayName}const vehicleDetails=document.getElementById("vehicle-details");if(vehicleDetails){const details=[];if(carDetails.car_type)details.push(carDetails.car_type);if(carDetails.fuel_type)details.push(carDetails.fuel_type);if(carDetails.gear_type)details.push(carDetails.gear_type);if(carDetails.num_passengers)details.push(`${carDetails.num_passengers} passengers`);vehicleDetails.textContent=details.join(" • ")}vehicleInfo.style.display="block"}catch(error){console.error("Error updating vehicle info:",error);if(vehicleInfo)vehicleInfo.style.display="none"}}getSelectedCar(){if(!this.selectElement)return null;const selectedOption=this.selectElement.options[this.selectElement.selectedIndex];if(!selectedOption||!selectedOption.value)return null;return{id:selectedOption.getAttribute("data-car-id"),value:selectedOption.value,display_name:selectedOption.textContent,image_src:selectedOption.getAttribute("data-src"),daily_price:selectedOption.getAttribute("data-daily-price")}}setSelectedCar(carId){if(!this.selectElement)return false;const options=this.selectElement.querySelectorAll("option");for(let option of options){if(option.getAttribute("data-car-id")===carId.toString()){this.selectElement.value=option.value;this.selectElement.dispatchEvent(new Event("change"));return true}}return false}defaultOnLoad(cars){}defaultOnError(errorMessage){}init(){if(!this.selectElement){return}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",()=>{this.loadAvailableCars()})}else{this.loadAvailableCars()}}}if(document.readyState!=="loading"){const carsLoader=new DynamicCarsLoader;carsLoader.init()}else{document.addEventListener("DOMContentLoaded",()=>{const carsLoader=new DynamicCarsLoader;carsLoader.init()})}window.DynamicCarsLoader=DynamicCarsLoader;